per_step.command:
cat << 'EOF' > /usr/local/bin/generalize_rare.sh
#!/bin/bash
awk -F, '
BEGIN {OFS=","}
NR==FNR {
  if (NR>1) count[$2]++
  next
}
FNR==1 {print; next}
{
  if (count[$2] < 10) $2="DX-Rare"
  print
}
' /app/data/deid/patients.csv /app/data/deid/patients.csv > /app/data/deid/patients_gen.csv
mv /app/data/deid/patients_gen.csv /app/data/deid/patients.csv
EOF
chmod +x /usr/local/bin/generalize_rare.sh
/usr/local/bin/generalize_rare.sh
